import "./modal.scss";

const Modal = ({ isOpen, onClose }) => {
  if (!isOpen) return null;

  return (
    <div className="modal">
      <div className="modal-content">
        <span className="close" onClick={onClose}>&times;</span>
        <p>Это модальное окно!</p>
      </div>
    </div>
  );
};

export default Modal;
